<?php namespace App\Http\Controllers; use App\Models\Example; use Illuminate\Http\Request; class ExampleController extends Controller { public function handle(Request $request) { if($request->isMethod('get')) return response()->json(Example::latest()->get()); abort_unless($request->user()?->role === 'admin', 403); $data=$request->validate(['title'=>'required|string','description'=>'nullable|string','payload'=>'nullable|array']); return response()->json(Example::create($data),201); } }
